const char* ResolveSymbol(u32 address, u32* offset)
{
  std::size_t lo = 0;
  std::size_t hi = std::size(s_symbols);
  while (lo < hi)
  {
    const std::size_t mid = lo + (hi - lo) / 2;
    const Entry& e = s_symbols[mid];
    if (address < e.address)
      hi = mid;
    else if (address >= e.address + e.size)
      lo = mid + 1;
    else
    {
      if (offset != nullptr)
        *offset = address - e.address;
      return e.name;
    }
  }
  return nullptr;
}

std::size_t SymbolCount()
{
  return std::size(s_symbols);
}
